from collections import deque

def bfs_at_depth(graph, start, target_depth):
    if start not in graph:
        return []  # No outgoing edges from start node

    visited = set()
    queue = deque([(start, 0)])  # (node, depth)
    result = set()

    while queue:
        node, depth = queue.popleft()

        if depth > target_depth:
            continue

        if depth == target_depth:
            result.add(node)
            continue

        if node in visited:
            continue

        visited.add(node)

        for neighbor in graph[node]:
            if neighbor not in visited:
                queue.append((neighbor, depth + 1))

    return sorted(list(result))

# Execute BFS at depth 4
result_nodes = bfs_at_depth(graph, start_node, depth)
print(f"Nodes at depth {depth} from {start_node}: {result_nodes}")
